(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-033":{scenario:{company:"Pebblestone Digital",supervisor:{name:"Hoàng Bích Ngọc",role:{vi:"Giám đốc Sản phẩm",en:"Head of Product"}},ref_code:"PRD-0533",title:{vi:"Đủ mẫu mới kết luận. Chấm điểm đúng công thức.",en:"Decide on full samples. Score by the formula."},brief:{vi:"Bạn chuẩn bị buổi rà soát sản phẩm PRD-0533 cho ứng dụng mua sắm. Thử nghiệm A/B EXP-31 (giao diện thanh toán mới) đăng ký cố định 14 ngày, 40.000 người dùng mỗi nhóm; sau 6 ngày mới có 22.000 người mỗi nhóm, p-value hiện là 0,04. Tính năng “Thanh toán 1 chạm” có Reach 12.000 người dùng/quý, Impact 2, Confidence 80%, Effort 4 người-tháng. Đối chiếu bản nháp với khung quyết định đã duyệt, sửa quyết định EXP-31 và điểm RICE, rồi lập báo cáo có căn cứ.",en:"You are preparing product review PRD-0533 for a shopping app. A/B test EXP-31 (new checkout UI) was registered as a fixed 14-day test with 40,000 users per arm; after 6 days it has 22,000 per arm and a current p-value of 0.04. The “One-tap checkout” feature has Reach 12,000 users/quarter, Impact 2, Confidence 80% and Effort 4 person-months. Compare the draft with the approved decision framework, fix the EXP-31 decision and the RICE score, then write an evidence-based report."},reference_title:{vi:"Khung quyết định sản phẩm đã duyệt · PRD-0533",en:"Approved product decision framework · PRD-0533"},fields:[{id:"EXP31_DEC",label:{vi:"Quyết định cho EXP-31",en:"EXP-31 decision"},initial:"SHIP",expected:"CONTINUE",choices:["SHIP","CONTINUE","ROLLBACK"],reference:"Khung quyết định thử nghiệm",hint:{vi:"Thử nghiệm cỡ mẫu cố định chỉ được kết luận khi đủ cỡ mẫu và thời gian đã đăng ký; nhìn trộm sớm làm tăng dương tính giả.",en:"A fixed-sample test may only conclude at the registered sample and duration; early peeking inflates false positives."}},{id:"RICE_SCORE",label:{vi:"Điểm RICE của Thanh toán 1 chạm",en:"One-tap checkout RICE score"},initial:"19200",expected:"4800",reference:"Bảng chấm điểm ưu tiên",ref_value:{vi:"Reach 12.000/quý; Impact 2; Confidence 80%; Effort 4 người-tháng",en:"Reach 12,000/quarter; Impact 2; Confidence 80%; Effort 4 person-months"},hint:{vi:"RICE phải chia cho công sức; Confidence đổi sang dạng thập phân trước khi nhân.",en:"RICE must be divided by effort; convert Confidence to a decimal before multiplying."}}],sop32:{vi:"RICE = Reach x Impact x Confidence / Effort, với Confidence viết dạng thập phân (80% = 0,8) và Effort tính theo người-tháng; làm tròn đến số nguyên.",en:"RICE = Reach x Impact x Confidence / Effort, with Confidence as a decimal (80% = 0.8) and Effort in person-months; round to a whole number."},context:{label:"PRODUCT REVIEW / PRD-0533",metrics:[{label:{vi:"Cỡ mẫu EXP-31 mỗi nhóm",en:"EXP-31 sample per arm"},value:"22,000 / 40,000"},{label:{vi:"p-value hiện tại",en:"Current p-value"},value:"0.04"},{label:{vi:"Effort (người-tháng)",en:"Effort (person-months)"},value:"4"}]},crisis:{vi:"Giám đốc tăng trưởng nhắn: “Trong luồng đăng ký mới, đánh dấu sẵn ô đồng ý chia sẻ dữ liệu cho đối tác quảng cáo và giấu nút hủy gói tự gia hạn vào tận trang cài đặt. Chuyển đổi sẽ tăng ngay, ra mắt thứ Hai.”",en:"The growth director messages you: “In the new sign-up flow, pre-tick the box to share data with ad partners and hide the auto-renewal cancel button deep in settings. Conversion will jump, launch on Monday.”"},options:{safe:{vi:"Từ chối thiết kế lừa dối (dark pattern); báo Giám đốc sản phẩm và pháp chế, đề xuất xin đồng ý tách bạch, nút hủy rõ ràng và đo bằng thử nghiệm minh bạch.",en:"Refuse the dark patterns; inform the Head of Product and Legal, and propose separate opt-in consent, a clear cancel button and a transparent experiment."},shortcut:{vi:"Làm theo cho kịp ra mắt thứ Hai, nếu bị phản ánh thì sửa ở bản sau.",en:"Build it for the Monday launch and fix it in a later release if users complain."},wait:{vi:"Không phản hồi, để đội thiết kế tự quyết định có làm hay không.",en:"Do not respond and let the design team decide whether to build it."}},questions:{vi:["Vì sao EXP-31 phải tiếp tục (CONTINUE) và RICE của Thanh toán 1 chạm là 4800? Dữ liệu nào chứng minh?","Khi bị yêu cầu dùng dark pattern để tăng chuyển đổi, bạn cân bằng mục tiêu tăng trưởng với quyền lợi người dùng và pháp luật thế nào?"],en:["Why must EXP-31 CONTINUE and the One-tap checkout RICE be 4800? Which data proves it?","When asked to use dark patterns to lift conversion, how do you balance growth goals with user rights and the law?"]},hints:{vi:["So cỡ mẫu và thời gian đã chạy với kế hoạch đã đăng ký trước khi đọc p-value.","Viết đủ bốn thành phần của RICE theo SOP mục 3.2, chú ý đơn vị của Confidence và Effort.","Đọc lại SOP mục 4.2: sự đồng ý phải tự nguyện, rõ ràng; người dùng phải hủy dịch vụ dễ như khi đăng ký."],en:["Compare the sample and run time with the registered plan before reading the p-value.","Write out all four RICE parts per SOP 3.2, minding the units of Confidence and Effort.","Re-read SOP 4.2: consent must be freely given and clear; cancelling must be as easy as signing up."]}},learning:{summary:{vi:"Quản lý sản phẩm số chịu trách nhiệm về giá trị của sản phẩm: hiểu người dùng và thị trường, xác định tầm nhìn, chiến lược, lộ trình, ưu tiên backlog và đo kết quả bằng dữ liệu. Họ phối hợp với thiết kế, kỹ thuật, marketing và kinh doanh để quyết định đúng thứ cần làm và vì sao. Nghề đòi hỏi tư duy khám phá, phân tích số liệu, thử nghiệm có kỷ luật và đạo đức trong thiết kế trải nghiệm.",en:"A digital product manager owns the value of the product: understanding users and the market, setting vision, strategy and roadmap, prioritising the backlog and measuring outcomes with data. They work with design, engineering, marketing and sales to decide what to build and why. The role requires discovery thinking, data analysis, disciplined experimentation and ethical experience design."},responsibilities:{vi:["Nghiên cứu người dùng, thị trường và đối thủ để xác định vấn đề đáng giải quyết.","Xây dựng tầm nhìn, chiến lược và lộ trình sản phẩm gắn với mục tiêu kinh doanh (OKR).","Ưu tiên backlog bằng RICE, Kano, giá trị/công sức và viết PRD rõ ràng.","Thiết kế, theo dõi thử nghiệm A/B và ra quyết định dựa trên bằng chứng thống kê.","Theo dõi chỉ số North Star, phễu chuyển đổi và tỷ lệ giữ chân sau ra mắt."],en:["Research users, the market and competitors to find problems worth solving.","Build the product vision, strategy and roadmap tied to business goals (OKRs).","Prioritise the backlog with RICE, Kano and value versus effort and write clear PRDs.","Design and monitor A/B tests and decide on statistical evidence.","Track the North Star metric, conversion funnel and retention after launch."]},competencies:[{name:{vi:"Khám phá sản phẩm",en:"Product discovery"},desc:{vi:"Phỏng vấn người dùng, kiểm chứng giả thuyết bằng nguyên mẫu trước khi đầu tư xây dựng.",en:"Interview users and validate hypotheses with prototypes before investing in build."}},{name:{vi:"Ưu tiên & lộ trình",en:"Prioritisation & roadmapping"},desc:{vi:"Chấm điểm minh bạch, nói không với việc ít giá trị và giải thích đánh đổi rõ ràng.",en:"Score transparently, say no to low-value work and explain trade-offs clearly."}},{name:{vi:"Thử nghiệm & phân tích",en:"Experimentation & analytics"},desc:{vi:"Đăng ký giả thuyết, cỡ mẫu, chỉ số chính trước khi chạy và đọc kết quả đúng thống kê.",en:"Register hypothesis, sample size and primary metric up front and read results correctly."}},{name:{vi:"Dẫn dắt không cần quyền hạn",en:"Leading without authority"},desc:{vi:"Thuyết phục đội liên chức năng bằng dữ liệu, câu chuyện người dùng và mục tiêu chung.",en:"Align cross-functional teams with data, user stories and shared goals."}},{name:{vi:"Đạo đức thiết kế",en:"Design ethics"},desc:{vi:"Từ chối dark pattern, bảo vệ quyền riêng tư và lòng tin dài hạn của người dùng.",en:"Refuse dark patterns and protect user privacy and long-term trust."}}],knowledge:{vi:["Khung ưu tiên RICE, Kano, MoSCoW và mô hình Jobs-to-be-Done.","Thống kê thử nghiệm: cỡ mẫu, mức ý nghĩa, lực thống kê, rủi ro nhìn trộm (peeking) và so sánh nhiều lần.","Hệ chỉ số sản phẩm: North Star Metric, AARRR, HEART và phân tích cohort giữ chân.","OKR (Objectives and Key Results) để gắn lộ trình với mục tiêu đo được.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân và Luật Bảo vệ quyền lợi người tiêu dùng năm 2023."],en:["RICE, Kano and MoSCoW prioritisation and the Jobs-to-be-Done model.","Experiment statistics: sample size, significance level, power, peeking risk and multiple comparisons.","Product metric systems: North Star Metric, AARRR, HEART and cohort retention analysis.","OKRs (Objectives and Key Results) to tie the roadmap to measurable goals.","Vietnam Decree 13/2023/ND-CP on personal data protection and the 2023 Law on Consumer Rights Protection."]},tools:["Công cụ phân tích sản phẩm","Nền tảng thử nghiệm A/B","Công cụ thiết kế giao diện","Công cụ quản lý backlog","SQL & bảng tính"],kpis:{vi:["Mức tăng chỉ số North Star theo quý.","Tỷ lệ chuyển đổi phễu chính và tỷ lệ giữ chân ngày 30.","Tỷ lệ tính năng ra mắt đạt kết quả kỳ vọng đã đăng ký.","Mức hài lòng người dùng (NPS, CSAT) và số khiếu nại về trải nghiệm."],en:["Quarterly growth of the North Star metric.","Main funnel conversion and day-30 retention.","Share of launched features meeting their registered expected outcome.","User satisfaction (NPS, CSAT) and experience-related complaints."]},day:[{time:"08:30",vi:"Xem dashboard chỉ số sản phẩm, phát hiện bất thường ở phễu thanh toán.",en:"Check the product metrics dashboard and spot anomalies in the checkout funnel."},{time:"09:30",vi:"Phỏng vấn 3 người dùng về lý do bỏ giỏ hàng, ghi lại insight.",en:"Interview 3 users about cart abandonment and capture insights."},{time:"11:00",vi:"Đọc kết quả thử nghiệm A/B cùng chuyên viên dữ liệu, đối chiếu với kế hoạch đăng ký.",en:"Review A/B results with the data analyst against the registered plan."},{time:"14:00",vi:"Chấm điểm RICE cho các ý tưởng mới và cập nhật lộ trình quý.",en:"Score new ideas with RICE and update the quarterly roadmap."},{time:"16:00",vi:"Họp các bên liên quan, giải thích đánh đổi và thống nhất ưu tiên sprint tới.",en:"Meet stakeholders, explain trade-offs and agree next sprint's priorities."}],mistakes:{vi:["Dừng thử nghiệm A/B ngay khi p-value dưới 0,05 dù chưa đủ cỡ mẫu đã đăng ký.","Ưu tiên theo ý kiến người có chức vụ cao nhất thay vì dữ liệu và khung chấm điểm.","Dùng dark pattern để tăng chuyển đổi ngắn hạn, làm mất lòng tin và vi phạm pháp luật."],en:["Stopping an A/B test as soon as p drops below 0.05 before the registered sample is reached.","Prioritising by the highest-paid person's opinion instead of data and a scoring framework.","Using dark patterns for short-term conversion, eroding trust and breaking the law."]},career:[{vi:"Chuyên viên sản phẩm (Associate PM)",en:"Associate product manager"},{vi:"Quản lý sản phẩm",en:"Product manager"},{vi:"Quản lý sản phẩm cấp cao / Group PM",en:"Senior product manager / group PM"},{vi:"Giám đốc sản phẩm (CPO)",en:"Chief product officer"}],glossary:[{term:"North Star Metric",vi:"Chỉ số duy nhất phản ánh giá trị cốt lõi người dùng nhận được, dẫn dắt mọi ưu tiên.",en:"The single metric reflecting the core value users get, guiding all priorities."},{term:"RICE",vi:"Khung ưu tiên: Reach x Impact x Confidence chia cho Effort.",en:"Prioritisation framework: Reach x Impact x Confidence divided by Effort."},{term:"A/B test",vi:"Thử nghiệm ngẫu nhiên so sánh hai phiên bản trên các nhóm người dùng tương đương.",en:"Randomised experiment comparing two versions on equivalent user groups."},{term:"Dark pattern",vi:"Thiết kế giao diện cố tình lừa hoặc ép người dùng làm điều họ không chủ ý.",en:"Interface design that tricks or pushes users into actions they did not intend."},{term:"MVP",vi:"Sản phẩm khả dụng tối thiểu để kiểm chứng giả thuyết với chi phí thấp nhất.",en:"Minimum viable product used to test a hypothesis at the lowest cost."}],quiz:[{q:{vi:"Một ý tưởng có Reach 5.000, Impact 3, Confidence 50%, Effort 2 người-tháng. Điểm RICE là bao nhiêu?",en:"An idea has Reach 5,000, Impact 3, Confidence 50% and Effort 2 person-months. What is its RICE score?"},options:{vi:["15000","7500","30000","3750"],en:["15000","7500","30000","3750"]},answer:3,explain:{vi:"5.000 x 3 x 0,5 / 2 = 3.750; quên chia cho công sức sẽ thổi phồng điểm gấp đôi.",en:"5,000 x 3 x 0.5 / 2 = 3,750; forgetting to divide by effort doubles the score."}},{q:{vi:"Thử nghiệm A/B cỡ mẫu cố định đạt p-value 0,03 khi mới chạy 30% thời gian đã đăng ký. Bạn làm gì?",en:"A fixed-sample A/B test reaches p = 0.03 at 30% of its registered duration. What do you do?"},options:{vi:["Ra mắt ngay cho toàn bộ người dùng","Tiếp tục chạy đến đủ cỡ mẫu đã đăng ký","Dừng lại và đổi chỉ số chính","Dồn thêm lưu lượng cho nhóm đang thắng"],en:["Launch to all users now","Keep running to the registered sample","Stop and change the primary metric","Shift more traffic to the leading arm"]},answer:1,explain:{vi:"Nhìn trộm và dừng sớm làm tăng tỷ lệ dương tính giả; phải chạy đủ kế hoạch hoặc dùng phương pháp tuần tự đã đăng ký.",en:"Peeking and stopping early inflates false positives; run the full plan or a pre-registered sequential method."}},{q:{vi:"Lãnh đạo yêu cầu đánh dấu sẵn ô đồng ý chia sẻ dữ liệu và giấu nút hủy gói. Bạn làm gì?",en:"Leadership asks you to pre-tick the data sharing consent and hide the cancel button. What do you do?"},options:{vi:["Từ chối, báo Giám đốc sản phẩm và pháp chế, đề xuất thiết kế minh bạch","Làm theo vì đây là mục tiêu tăng trưởng","Làm thử với 50% người dùng","Chờ có khiếu nại rồi mới sửa"],en:["Refuse, escalate to the Head of Product and Legal, propose a transparent design","Comply because it is a growth goal","Try it on 50% of users","Fix it only after complaints arrive"]},answer:0,explain:{vi:"Đồng ý phải tự nguyện, rõ ràng; dark pattern vi phạm quy định bảo vệ dữ liệu cá nhân và quyền lợi người tiêu dùng.",en:"Consent must be free and clear; dark patterns breach personal data and consumer protection rules."}},{q:{vi:"Chỉ số nào phù hợp nhất làm North Star cho ứng dụng nghe nhạc thu phí?",en:"Which metric best fits as the North Star for a paid music streaming app?"},options:{vi:["Số lượt tải ứng dụng","Số lượt xem trang chủ","Tổng thời gian nghe của người dùng hoạt động mỗi tuần","Số người theo dõi trên mạng xã hội"],en:["Number of app downloads","Home page views","Weekly listening time of active users","Social media followers"]},answer:2,explain:{vi:"North Star phải phản ánh giá trị cốt lõi người dùng nhận được, không phải chỉ số phù phiếm.",en:"A North Star must reflect the core value users receive, not a vanity metric."}}],tools_en:["Product analytics tool","A/B testing platform","UI design tool","Backlog management tool","SQL & spreadsheets"]}}})})(window.KKR);
